-- ====================================================================
-- OMNIPOLL - SCRIPT DE ACTUALIZACIÓN DE DATOS (MIGRACIÓN / PARCHE)
-- Ejecutar sobre una base de datos existente para incorporar:
-- 1. Todos los usuarios (rllamoza, admin, carlos.valdivia, elena.ramos, marco.polo, cliente)
-- 2. Encuesta CCAVX024 con sus 4 preguntas, 86 opciones y branding
-- 3. 500 Respuestas completas de CCAVX024 con priorización de Redes y Sedes
-- 4. Asignaciones de encuestas a clientes
-- ====================================================================

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '-05:00';

-- 1. Asegurar estructura de usuarios y tabla usuario_encuestas
ALTER TABLE `usuarios` MODIFY COLUMN `rol` VARCHAR(50) NOT NULL DEFAULT 'encuestador';
CREATE TABLE IF NOT EXISTS `usuario_encuestas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int NOT NULL,
  `encuesta_id` int NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_usuario_encuesta` (`usuario_id`,`encuesta_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Usuarios del Sistema con contraseña 'admin123'
ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`), `password_hash` = VALUES(`password_hash`), `rol` = VALUES(`rol`), `cargo` = VALUES(`cargo`), `activo` = 1;

-- 3. Encuesta CCAVX024
ON DUPLICATE KEY UPDATE `titulo` = VALUES(`titulo`), `branding_json` = VALUES(`branding_json`), `estado` = 'aprobada';

-- Secciones de CCAVX024
ON DUPLICATE KEY UPDATE `titulo` = VALUES(`titulo`);

-- Preguntas de CCAVX024
ON DUPLICATE KEY UPDATE `enunciado` = VALUES(`enunciado`), `tipo` = VALUES(`tipo`);

-- Opciones de Pregunta de CCAVX024 (86 opciones)
DELETE FROM `opciones_pregunta` WHERE `pregunta_id` IN (SELECT id FROM preguntas WHERE encuesta_id = 24);

-- 4. Asignaciones de Encuestas a Cliente
SELECT u.id, 24 FROM usuarios u WHERE u.email = 'cliente@empresa.pe';
SELECT u.id, 1 FROM usuarios u WHERE u.email = 'cliente@empresa.pe';

-- 5. Respuestas de Encuesta CCAVX024 (500 respuestas)
DELETE FROM `respuestas_encuesta` WHERE `encuesta_id` = 24;

-- 6. Detalle de Respuestas individuales (2000 registros)

SET FOREIGN_KEY_CHECKS = 1;
-- Fin del script de actualización
